package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarArchiveInputStream.read(byte[], int, int)
 * Designed to maximize branch and line coverage.
 */
public class TarArchiveInputStream_read_TriageGen1Test {

    /**
     * Helper to create a valid minimal Tar stream.
     * A Tar entry consists of a 512-byte header followed by data (padded to 512).
     */
    private byte[] createTarStream(byte[] data) throws IOException {
        byte[] header = new byte[512];
        // Set name length to something valid
        header[0] = 0; 
        // Set file size in header (octal) - simplified for testing
        // We'll just use a raw byte array approach to simulate the stream
        // But since we are testing the 'read' method of the stream, 
        // we need to provide a stream that satisfies the buffer.readRecord() logic.
        // In TarArchiveInputStream, readRecord() reads 512-byte blocks.

        int dataLen = data.length;
        int padding = (512 - (dataLen % 512)) % 512;
        byte[] fullStream = new byte[512 + dataLen + padding];

        // Very basic header simulation: 
        // The actual implementation of TarArchiveInputStream relies on the underlying 
        // buffer.readRecord(). We will mock the behavior by providing valid tar-like data.
        // However, since we can't easily mock the private 'buffer' field, we provide 
        // a real stream that contains a valid header and data.

        // For the purpose of this test, we assume the constructor and getNextEntry 
        // will advance the internal state to a point where 'read' is called on an entry.
        return fullStream; 
    }

    @Test
    public void testRead_EOF() throws IOException {
        // Empty stream
        InputStream is = new ByteArrayInputStream(new byte[0]);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            byte[] buf = new byte[10];
            // If no entry is present, entryOffset >= entrySize will likely trigger or return -1
            // depending on how the parser initialized.
            int result = tais.read(buf, 0, 10);
            // If we haven't even started an entry, it should return -1 or throw
            // Depending on internal state.
        }
    }

    @Test
    public void testRead_AlreadyAtEOF() throws IOException {
        // Create a stream with one empty entry to reach the end of entry data
        // This is complex to do with raw bytes manually, so we use a simplified approach
        // to trigger the logic: if (entryOffset >= entrySize) return -1;

        // We use a real Tar stream via a byte array for reliability
        byte[] tarData = new byte[1024]; // Contains dummy header and 512 bytes of 0
        InputStream is = new ByteArrayInputStream(tarData);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            tais.getNextTarEntry(); // Move to first entry

            // Read all data
            byte[] buf = new byte[1024];
            tais.read(buf, 0, 512);

            // Now entryOffset == entrySize
            int result = tais.read(buf, 0, 10);
            assertEquals(-1, result);
        }
    }

    @Test
    public void testRead_NumToReadExceedsRemainingEntrySize() throws IOException {
        // Test: if ((numToRead + entryOffset) > entrySize) { numToRead = (int) (entrySize - entryOffset); }
        // We need a stream where entrySize is known.
        // Since we can't easily control 'entrySize' via public API without a real tar,
        // we simulate a small entry.

        byte[] data = new byte[10];
        // Construct a valid tar header for a 10-byte file
        // Header is 512 bytes. Data is 10 bytes. Total entry size = 10.
        // We use a real Tar format here to ensure the internal state is correct.
        byte[] tar = createMinimalTar(data);

        InputStream is = new ByteArrayInputStream(tar);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            tais.getNextTarEntry();

            byte[] buf = new byte[100];
            // entryOffset is 0. numToRead is 100. entrySize is 10.
            // 100 + 0 > 10 -> numToRead becomes 10.
            int read = tais.read(buf, 0, 100);
            assertEquals(10, read);
        }
    }

    @Test
    public void testRead_WithExistingReadBuf() throws IOException {
        // Test the logic: if (readBuf != null)
        // This happens when a previous read left some bytes in the 'readBuf' cache.

        byte[] data = new byte[20];
        for(int i=0; i<20; i++) data[i] = (byte)i;
        byte[] tar = createMinimalTar(data);

        InputStream is = new ByteArrayInputStream(tar);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            tais.getNextTarEntry();

            byte[] buf = new byte[15];
            // First read: takes 15 bytes. 5 bytes remain in readBuf.
            int firstRead = tais.read(buf, 0, 15);
            assertEquals(15, firstRead);

            // Second read: should use readBuf. 
            // sz = min(5, 15) = 5.
            // System.arraycopy(readBuf, 0, buf, offset, 5)
            byte[] buf2 = new byte[10];
            int secondRead = tais.read(buf2, 0, 10);
            assertEquals(5, secondRead);

            // Check if content is correct (the remaining 5 bytes from the 20)
            for(int i=0; i<5; i++) {
                assertEquals((byte)(15 + i), buf2[i]);
            }
        }
    }

    @Test
    public void testRead_RecLenGreaterThanSz() throws IOException {
        // Test: if (recLen > sz) { ... readBuf = new byte[recLen - sz]; ... }
        // This occurs when the record returned by buffer.readRecord() is larger than requested.

        byte[] data = new byte[512]; // Exactly one block
        byte[] tar = createMinimalTar(data);

        InputStream is = new ByteArrayInputStream(tar);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(is)) {
            tais.getNextTarEntry();

            byte[] buf = new byte[10];
            // Requesting 10 bytes when the record is 512.
            // recLen (512) > sz (10).
            int read = tais.read(buf, 0, 10);
            assertEquals(10, read);

            // The next read should pull from the remaining 502 bytes in readBuf
            byte[] buf2 = new byte[10];
            int read2 = tais.read(buf2, 0, 10);
            assertEquals(10, read2);
        }
    }

    @Test(expected = IOException.class)
    public void testRead_UnexpectedEOF() throws IOException {
        // Test: if (rec == null) throw new IOException(...)
        // We simulate this by providing a stream that ends abruptly mid-record.
        // However, TarArchiveInputStream reads 512-byte blocks.
        // If we provide a stream that is exactly 512 bytes (one header) and no more,
        // and we try to read more data, the next readRecord() will return null.

        byte[] headerOnly = new byte[512]; 
        // This is technically a valid header for a 0-byte file, but if we 
        // try to read more than 0 bytes, it might trigger.
        // Actually, to trigger rec == null, we need the buffer to think there's data but return null.
        // This is hard with standard InputStream. We'll use a custom InputStream.

        InputStream abruptIs = new InputStream() {
            @Override public int read() { return 0; }
            @Override public int read(byte[] b, int off, int len) { return -1; } // Immediate EOF
        };

        try (TarArchiveInputStream tais = new TarArchiveInputStream(abruptIs)) {
            // We need to get past the header check. 
            // Since the header is read by getNextEntry, and our stream is empty,
            // getNextEntry will likely return null.
            // To reach the 'while(numToRead > 0)' loop, we need to be inside an entry.

            // This is a bit of a catch-22 with the real TarArchiveInputStream implementation,
            // but we can simulate the state by using a stream that provides a header 
            // but then returns -1.
            byte[] header = new byte[512];
            // Set size to 10 in header
            header[124] = 10; // Very hacky, but enough to make the parser expect data

            InputStream is = new ByteArrayInputStream(header);
            // We need a way to force the stream to return -1 after the first 512 bytes.
            // A custom InputStream that returns 512 bytes then -1.
            InputStream customIs = new InputStream() {
                int count = 0;
                @Override public int read() { return (count++ < 512) ? 0 : -1; }
                @Override public int read(byte[] b, int off, int len) {
                    if (count >= 512) return -1;
                    int toRead = Math.min(len, 512 - count);
                    count += toRead;
                    return toRead;
                }
            };

            TarArchiveInputStream tais2 = new TarArchiveInputStream(customIs);
            tais2.getNextTarEntry();
            byte[] buf = new byte[10];
            tais2.read(buf, 0, 10); // Should throw IOException
        }
    }

    /**
     * Helper to create a valid minimal Tar stream containing one file.
     */
    private byte[] createMinimalTar(byte[] data) throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(512 + data.length + 512);
        byte[] header = new byte[512];

        // Set file size in header (offset 124, octal)
        String sizeStr = String.format("%07o", data.length);
        for (int i = 0; i < sizeStr.length(); i++) {
            header[124 + i] = (byte) sizeStr.charAt(i);
        }
        // Set file mode (offset 100)
        header[100] = 0644;

        bb.put(header);
        bb.put(data);
        // Padding to 512
        int padding = (512 - (data.length % 512)) % 512;
        bb.put(new byte[padding]);
        // End of archive marker (two 512 zero blocks)
        bb.put(new byte[512]);
        bb.put(new byte[512]);

        return bb.array();
    }
}
